<?php
namespace App\Core\Audit;use App\Models\AuditEvent;
final class AuditLogger {public function record(?int $workspaceId,string $event,?string $subjectType=null,string|int|null $subjectId=null,array $data=[],?string $runId=null,?int $actorUserId=null):AuditEvent{$previous=AuditEvent::where('workspace_id',$workspaceId)->latest('id')->value('hash');$created=now();$payload=['workspace_id'=>$workspaceId,'actor_user_id'=>$actorUserId,'run_id'=>$runId,'event'=>$event,'subject_type'=>$subjectType,'subject_id'=>$subjectId!==null?(string)$subjectId:null,'data'=>$data,'previous_hash'=>$previous,'created_at'=>$created->toIso8601String()];$hash=hash('sha256',($previous??'GENESIS').'|'.json_encode($payload,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE));return AuditEvent::create(array_merge($payload,['hash'=>$hash,'created_at'=>$created]));}}
